erDiagram
 CUSTOMER ||--o{ ORDER : places
 CUSTOMER {
  int id PK
  string name
 }
 ORDER {
  int id PK
  int customer_id FK
 }

requirementDiagram
 requirement storage {
 id: 1
 text: Store records
 risk: low
 verifymethod: test
 }
 element worker {
 type: service
 }
 worker - satisfies -> storage

railroad-beta
 root = sequence(terminal("start"), optional(nonterminal("item")), zeroOrMore(choice(terminal("a"), terminal("b"))));
 item = terminal("value");

railroad-ebnf-beta
root = "start", [ item ], { "a" | "b" };
item = "value";

railroad-abnf-beta
root = "start" [item] *("a" / "b");
item = "value";

railroad-peg-beta
root <- "start" item? ("a" / "b")*;
item <- "value";

classDiagram
 direction LR
 namespace Domain {
 class Record {
 +String id
 +save() bool
 }
 class Repository
 }
 Record "1" --> "many" Repository : uses
 note for Record "A stored record"

stateDiagram-v2
 state Parallel {
 [*] --> First
 --
 [*] --> Second
 }

C4Component
 Container_Boundary(b, "API") {
